const{spawnSync}=require("child_process");
const items=JSON.parse(process.argv[2]);
function vis(s){
  let o="";
  for(const c of s){
    const cp=c.codePointAt(0);
    if(c==="\t") o+="\\t";
    else if(c==="\n") o+="\\n";
    else if(cp<0x20||cp===0x7f||(cp>=0x80&&cp<=0xa0)||cp===0x2028||cp===0x2029||cp===0xfeff||cp===0xfffd||cp>0x7e&&cp<0xff&&cp!==0xe9)
      o+= cp<=0xff?"\\x"+cp.toString(16).padStart(2,"0"):"\\u"+cp.toString(16).padStart(4,"0");
    else if(cp>0xffff) o+="\\U"+cp.toString(16).padStart(8,"0");
    else if(cp>0x7e) o+="\\u"+cp.toString(16).padStart(4,"0");
    else o+=c;
  }
  return o;
}
